/* Module 1: manual lead acquisition, qualification, referral and SLA. No AI. */
const LEAD_GUIDANCE={Cool:'Kebutuhan belum terkonfirmasi; lakukan kontak awal.',Warm:'Kebutuhan terkonfirmasi, informasi atau waktu pembelian belum lengkap.','Hot 1':'Kebutuhan dan produk sesuai; lengkapi data serta rencana tindak lanjut.','Hot 2':'Kebutuhan, kelengkapan awal dan target waktu sudah jelas; siap ditawarkan.'};
function leadCall(name,...args){return name+'('+args.map(x=>E(JSON.stringify(x))).join(',')+')'}
function leadPolicy(){return {responseDays:1,qualificationDays:5,branches:['BPD Bali HQ Renon','BPD Bali Capem Nusa Dua'],...db.config.leadWorkflow,guidance:{...LEAD_GUIDANCE,...db.config.leadWorkflow?.guidance}}}
function leadOpportunityCount(l){return db.leadOpportunityCounts?.[l.id]??db.opps.filter(o=>o.lead===l.id).length}
function linkedLeadHasOpportunity(l){return l.status==='Converted'||leadOpportunityCount(l)>0}
function leadOpportunities(l){return db.opps.filter(o=>o.lead===l.id&&mine(o))}
leadLifecycle=function(l){if(l.customerConverted||l.status==='CustomerConverted')return 'Dikonversi ke Customer';if(l.status==='Closed')return 'Ditutup';if(linkedLeadHasOpportunity(l))return 'Dikonversi ke Opportunity';if(l.qualification==='Qualified')return 'Qualified';if(l.qualification==='Tidak Qualified')return 'Tidak Qualified';return l.status==='New'?'Baru':'Dalam Kualifikasi'};
const LEAD_CHIPS=['Aktif','Semua','Baru','Dalam Kualifikasi','Qualified','Tidak Qualified','Dikonversi ke Opportunity','Dikonversi ke Customer','Ditutup'];
function leadMatchesChip(l,chip){const stage=leadLifecycle(l);return chip==='Semua'||chip==='Aktif'?!['Ditutup','Tidak Qualified','Dikonversi ke Opportunity','Dikonversi ke Customer'].includes(stage)||chip==='Semua':stage===chip.replace('Nasabah','Customer')}
const leadPreviousList=getList;
getList=function(name=view){if(name!=='Leads')return leadPreviousList(name);return db.leads.filter(l=>{const p=profile(l.profile);return mine(l)&&leadMatchesChip(l,leadChip)&&(!listOwner||l.owner===listOwner)&&(!listQuery||[p?.name,p?.phone,p?.nik,l.id,l.need,l.branch,l.referral].join(' ').toLowerCase().includes(listQuery.toLowerCase()))&&(!listSource||l.source===listSource)&&(!listGrade||l.grade===listGrade)&&(!listPeriod||l.created.startsWith(listPeriod))}).sort((a,b)=>String(b.recorded||b.created).localeCompare(String(a.recorded||a.created)))};
function leadSla(l){const stage=leadLifecycle(l);if(l.qualification==='Tidak Qualified'||['Ditutup','Dikonversi ke Customer','Dikonversi ke Opportunity'].includes(stage))return {label:'SLA selesai',late:false};const start=Date.parse(l.recorded||l.created),r=leadPolicy();if(!Number.isFinite(start))return {label:'Tanggal masuk belum tersedia',late:false};const contact=db.activities.some(a=>a.lead===l.id||a.profile===l.profile&&Date.parse(a.occurred||a.recorded)>=start),qualification=['Qualified','Tidak Qualified'].includes(l.qualification);const rows=[];if(!contact)rows.push({name:'Respons awal',at:start+Number(l.responseSlaDays??r.responseDays)*86400000});if(!qualification)rows.push({name:'Kualifikasi',at:start+Number(l.qualificationSlaDays??r.qualificationDays)*86400000});if(!rows.length)return {label:'Respons & kualifikasi selesai',late:false};rows.sort((a,b)=>a.at-b.at);const next=rows[0],late=Date.now()>next.at;return {label:next.name+(late?' lewat SLA':' jatuh tempo'),late,due:next.at,rows}}
function leadSlaBadge(l){const s=leadSla(l);return '<span class="lead-sla '+(s.late?'late':'')+'">'+E(s.label)+(s.due?' · '+E(fmt(new Date(s.due).toISOString())):'')+'</span>'}
leadRows=function(items){return '<div class="scrolltable"><table class="datatable"><thead><tr><th>Lead</th><th>Kebutuhan</th><th>Sumber</th><th>Status & SLA</th><th>Owner / Cabang</th><th></th></tr></thead><tbody>'+items.map(l=>'<tr><td><strong>'+E(pname(l.profile))+'</strong><small>'+E(l.id)+' · '+E(fmt(l.created))+'</small></td><td>'+E(l.need)+'<small>'+E(l.product)+'</small></td><td>'+E(l.source)+'<small>'+E(l.referral||l.campaignReference||l.digitalChannel||'')+'</small></td><td>'+badge(leadLifecycle(l))+'<small>Potensi: '+E(l.grade||'Belum dinilai')+'</small>'+leadSlaBadge(l)+'</td><td>'+E(l.owner)+'<small>'+E(l.branch||profile(l.profile)?.branch||'Belum ditetapkan')+'</small></td><td>'+btn('Detail',leadCall('go','Lead detail',l.id))+'</td></tr>').join('')+'</tbody></table></div>'};
mobileLead=function(l){return '<article class="record"><div class="recordtop">'+badge(leadLifecycle(l))+badge(l.grade||'Belum dinilai')+'</div><h3>'+E(pname(l.profile))+'</h3><p>'+E(l.need)+'</p><small>'+E(l.owner)+' · '+E(l.branch||'Cabang belum ditetapkan')+'</small>'+leadSlaBadge(l)+btn('Buka lead',leadCall('go','Lead detail',l.id))+'</article>'};
const leadPreviousScale=scaleList;
scaleList=function(){if(view!=='Leads')return leadPreviousScale();const items=getList('Leads'),slice=pageItems(items),all=db.leads.filter(mine);return titleBlock('Leads','Kualifikasi calon pelanggan. Lead yang sudah menjadi Opportunity dipisahkan dari antrean aktif.',btn('Lead baru','createLead()',true))+'<div class="rangechips leadchips">'+LEAD_CHIPS.map(c=>'<button class="'+(leadChip===c?'active':'')+'" onclick="leadChip=\''+c+'\';listPage=1;renderContent()">'+c+' <b>'+all.filter(l=>leadMatchesChip(l,c)).length+'</b></button>').join('')+'</div>'+commonFilters(filterSelect('Semua sumber','source',activeMaster('sources').map(s=>s.name),listSource)+filterSelect('Semua kategori','grade',quals,listGrade)+'<input aria-label="Bulan lead dibuat" type="month" value="'+E(listPeriod)+'" onchange="changeFilter(\'period\',this.value)">')+'<div class="listhead"><strong>'+items.length+' lead sesuai filter</strong><small>SLA dihitung dalam hari kalender.</small></div>'+(items.length?(mobile?'<div class="records">'+slice.map(mobileLead).join('')+'</div>':leadRows(slice)):empty('Tidak ada lead sesuai filter.'))+pager(items.length)};
function leadChoice(label,name,items,value='',required=false,onchange=''){return '<label>'+E(label)+'<select name="'+name+'" '+(required?'required':'')+' '+(onchange?'onchange="'+onchange+'"':'')+'><option value="">Pilih…</option>'+items.map(x=>{const [v,t]=Array.isArray(x)?x:[x,x];return '<option value="'+E(v)+'" '+(v===value?'selected':'')+'>'+E(t)+'</option>'}).join('')+'</select></label>'}
function leadSourceKind(name){return activeMaster('sources').find(s=>s.name===name)?.kind||(/referral/i.test(name)?'referral':/campaign/i.test(name)?'campaign':/digital/i.test(name)?'digital':/existing/i.test(name)?'existing':'input')}
function leadSourceInputs(l={}){return leadChoice('Sumber lead','source',activeMaster('sources').map(s=>s.name),l.source||activeMaster('sources')[0]?.name,true,'leadToggleSource()')+'<div data-lead-group="campaign">'+field('Nama / referensi campaign','campaignReference',l.campaignReference||'','text',true)+'</div><div data-lead-group="digital">'+field('Channel digital','digitalChannel',l.digitalChannel||'','text',true)+field('Referensi formulir / channel','digitalReference',l.digitalReference||'')+'</div><div data-lead-group="referral">'+leadChoice('Jenis referral','referralType',['Internal','Eksternal'],l.referralType||'Eksternal',true,'leadToggleSource()')+'<div data-lead-ref="internal">'+leadChoice('Anggota pemberi referral','referralMemberId',memberList.filter(m=>m.active!==false).map(m=>[m.id,m.name]),l.referralMemberId||'',true)+'</div><div data-lead-ref="external">'+field('Nama pemberi referral eksternal','referral',l.referral||'','text',true)+'</div>'+field('Cabang / organisasi pemberi referral','referralBranch',l.referralBranch||'')+select('Status penanganan referral','referralStatus',['Diterima','Dihubungi','Dalam proses','Tidak dilanjutkan'],['Diterima','Dihubungi','Dalam proses','Tidak dilanjutkan'].includes(l.referralStatus)?l.referralStatus:'Diterima')+'</div>'}
function leadGroup(el,show){if(!el)return;el.hidden=!show;for(const input of el.querySelectorAll('input,select,textarea'))input.disabled=!show}
function leadToggleSource(){const f=document.querySelector('#form');if(!f)return;const kind=leadSourceKind(f.elements.source.value);for(const el of f.querySelectorAll('[data-lead-group]'))leadGroup(el,el.dataset.leadGroup===kind);leadGroup(f.querySelector('[data-lead-ref="internal"]'),kind==='referral'&&f.elements.referralType.value==='Internal');leadGroup(f.querySelector('[data-lead-ref="external"]'),kind==='referral'&&f.elements.referralType.value!=='Internal');leadGroup(f.querySelector('#leadNewIdentity'),kind!=='existing');leadGroup(f.querySelector('#leadExistingCustomer'),kind==='existing')}
function leadSourceData(f){const kind=leadSourceKind(f.source);return {source:f.source,campaignReference:kind==='campaign'?f.campaignReference||'':'',digitalChannel:kind==='digital'?f.digitalChannel||'':'',digitalReference:kind==='digital'?f.digitalReference||'':'',referralType:kind==='referral'?f.referralType||'Eksternal':'',referralMemberId:kind==='referral'&&f.referralType==='Internal'?f.referralMemberId||'':'',referral:kind==='referral'?(f.referralType==='Internal'?memberList.find(m=>m.id===f.referralMemberId)?.name||'':f.referral||''):'',referralBranch:kind==='referral'?f.referralBranch||'':'',referralStatus:kind==='referral'?f.referralStatus||'Diterima':''}}
function leadFormError(error){const el=document.querySelector('#formerror');if(el)el.textContent=error.message||String(error);else toast(error.message)}
async function leadDuplicateCheck(){const f=document.querySelector('#form');try{const values=Object.fromEntries(new FormData(f)),r=await api('lead-duplicates',{phone:values.phone,nik:values.nik});const box=document.querySelector('#leadDuplicateResult');box.innerHTML=r.matches.length?r.matches.map(m=>'<div class="lead-match">'+E(m.name||'Data terdaftar pada cabang lain')+' · '+E(m.relation)+' · '+E(m.branch)+(m.accessible&&(m.relation==='Customer'||m.lead)?btn('Buka data',"document.querySelector('#modal').close();"+leadCall('go',m.relation==='Customer'?'Nasabah detail':'Lead detail',m.relation==='Customer'?m.profile:m.lead)):'<small>Hubungi SPV untuk koordinasi ownership.</small>')+'</div>').join(''):'<p>Tidak ditemukan kecocokan NIK / telepon pada workspace CRM.</p>'}catch(e){leadFormError(e)}}
const leadPreviousCreate=createLead;
let leadCreating=false;
createLead=function(){if(typeof journey!=='undefined'&&journey)return leadPreviousCreate();const rules=leadPolicy(),customers=db.profiles.filter(p=>p.relation==='Customer'&&mine(p));modal('Lead baru','<p class="hint">Cek NIK/telepon mencakup data pada workspace CRM ini, termasuk cabang lain yang tercatat. Belum terhubung ke database Bank eksternal.</p>'+leadSourceInputs()+'<div id="leadExistingCustomer">'+leadChoice('Customer existing','existingProfile',customers.map(p=>[p.id,p.name+' · '+(p.cif||'CIF belum tersedia')]),'',true)+'</div><div id="leadNewIdentity">'+field('Nama orang / perusahaan','name','','text',true)+field('Nama kontak','contact')+field('Nomor telepon','phone','','tel',true)+field('NIK (opsional, 16 digit)','nik')+field('Alamat','address')+field('Alamat usaha / tempat bekerja','businessAddress')+field('Pekerjaan / bidang usaha','occupation')+'<button type="button" onclick="leadDuplicateCheck()">Cek duplikasi lintas cabang</button><div id="leadDuplicateResult" aria-live="polite"></div></div>'+leadChoice('Cabang penanganan','branch',rules.branches,rules.branches[0],true)+select('Minat produk','product',['Belum diketahui',...activeMaster('products').map(x=>x.name)])+area('Kebutuhan awal','need','',true)+ownerSelect()+'<p class="hint">SLA respons awal '+rules.responseDays+' hari, kualifikasi '+rules.qualificationDays+' hari kalender. Berlaku pada Lead baru.</p>',f=>{if(leadCreating)return false;leadCreating=true;(async()=>{if(saving)throw Error('Tunggu penyimpanan selesai.');const existing=leadSourceKind(f.source)==='existing'||f.identityMode==='existing';let p=existing?profile(f.existingProfile):null;if(existing&&(!p||p.relation!=='Customer'||!mine(p)))throw Error('Pilih Customer existing yang dapat Anda akses.');if(!existing){if(f.nik&&!/^\d{16}$/.test(f.nik))throw Error('NIK harus 16 digit.');const check=await api('lead-duplicates',{phone:f.phone,nik:f.nik});if(check.matches.length)throw Error('NIK/telepon sudah tercatat. Gunakan data existing atau hubungi SPV cabang penanggung jawab.');p={id:uid('P'),name:f.name,contact:f.contact,phone:f.phone,nik:f.nik||'',address:f.address,businessAddress:f.businessAddress,occupation:f.occupation,branch:f.branch,owner:f.owner,relation:'Prospect'}}const l={id:uid('L'),profile:p.id,owner:f.owner,branch:f.branch,existingCustomer:existing,...leadSourceData(f),product:f.product,need:f.need,status:'New',qualification:'Belum dinilai',grade:'Cool',created:today(),recorded:now()};const changes=[...(!existing?[{collection:'profiles',id:p.id,before:null,next:p}]:[]),{collection:'leads',id:l.id,before:null,next:l}];const r=await api('sync',{changes,action:'Buat Lead',object:l.id,detail:existing?'Lead kebutuhan baru Customer existing':'Lead baru'});document.querySelector('#modal').close();applyServer(r);go('Lead detail',l.id);toast('Lead tersimpan')})().catch(leadFormError).finally(()=>{leadCreating=false});return false});leadToggleSource()};
assessment=function(id){let l;try{l=guardConvertedLead(id)}catch(e){return toast(e.message)}const a=l.assessment||{};modal('Survey & assessment awal',field('Tanggal survey','date',a.date||today(),'date',true)+area('Hasil survey','survey',a.survey||'',true)+area('Informasi usaha','business',a.business||'',true)+area('Gambaran keuangan awal','financial',a.financial||'',true)+area('Kesimpulan assessment','conclusion',a.conclusion||'',true)+'<p class="hint">Survey dapat membantu penilaian sebelum Lead dinyatakan Qualified. Informasi keuangan dicatat manual.</p>',f=>{l.assessment={...f,actor:actor(),recorded:now()};record('Assessment Lead',id,f.conclusion)})};
const leadPreviousQualify=qualify;
qualify=function(id){const l=db.leads.find(l=>l.id===id);if(!l||linkedLeadHasOpportunity(l))return toast('Lead sudah ditangani melalui Opportunity terkait.');leadPreviousQualify(id);const f=document.querySelector('#form');if(f)f.insertAdjacentHTML('afterbegin','<div class="lead-guide">'+Object.entries(leadPolicy().guidance).map(([k,v])=>'<p><b>'+E(k)+'</b> '+E(v)+'</p>').join('')+'</div>')};
const leadPreviousConvert=convertLeadCustomer;
convertLeadCustomer=function(id){const l=db.leads.find(l=>l.id===id);if(!l||l.qualification!=='Qualified'||l.status==='Closed')return toast('Lead harus Qualified sebelum dikonversi ke Customer.');if(profile(l.profile)?.relation==='Customer')return go('Nasabah detail',l.profile);leadPreviousConvert(id);const form=document.querySelector('#form'),p=profile(l.profile);if(form){if(form.elements.nik)form.elements.nik.value=p?.nik||'';if(form.elements.cif)form.elements.cif.value=p?.cif||'';}document.querySelector('#form')?.insertAdjacentHTML('afterbegin','<p class="hint">Konversi membentuk profil Customer CRM. Tidak membuka rekening atau membuat CIF pada sistem Bank.</p>')};
function leadEditSource(id){const l=db.leads.find(l=>l.id===id);if(!l)return;modal('Sumber, referral & cabang',leadSourceInputs(l)+leadChoice('Cabang penanganan','branch',leadPolicy().branches,l.branch||'',true),f=>{Object.assign(l,leadSourceData(f),{branch:f.branch});record('Perbarui sumber Lead',id,l.source)});leadToggleSource()}
const leadPreviousDetail=leadRecordDetail;
leadRecordDetail=function(l){let html=leadPreviousDetail(l);const box=document.createElement('div');box.innerHTML=html;box.querySelectorAll('.recordhero button').forEach(b=>{if((b.getAttribute('onclick')||'').includes('convertLeadCustomer')&&(l.qualification!=='Qualified'||l.status==='Closed'))b.remove()});if(l.customerConverted||linkedLeadHasOpportunity(l))box.querySelectorAll('button[onclick]').forEach(b=>{if(/qualify\(/.test(b.getAttribute('onclick')||'')||l.customerConverted&&/assessment\(/.test(b.getAttribute('onclick')||''))b.remove()});if(recordTab==='Referral')for(const h of box.querySelectorAll('h2'))if(h.textContent==='Asal dan perkembangan referral')h.closest('section')?.remove();if(l.status==='Closed')box.querySelectorAll('button[onclick]').forEach(b=>{if((b.getAttribute('onclick')||'').includes('newOpp('))b.remove()});for(const p of box.querySelectorAll('.hint'))if(p.textContent.includes('Kualifikasi Lead terlebih dahulu'))p.remove();html=box.innerHTML;const linked=leadOpportunities(l);let extra='<section class="panel lead-workflow-summary"><div class="recordtop">'+badge(leadLifecycle(l))+leadSlaBadge(l)+'</div>'+detailFacts([['Cabang penanganan',l.branch||profile(l.profile)?.branch||'Belum ditetapkan'],['Opportunity terkait',String(leadOpportunityCount(l))],['Asal',l.existingCustomer?'Kebutuhan Customer existing':'Akuisisi Lead'],['Respons awal',String(l.responseSlaDays??leadPolicy().responseDays)+' hari kalender'],['Kualifikasi',String(l.qualificationSlaDays??leadPolicy().qualificationDays)+' hari kalender']])+linked.map(oppCard).join('')+(l.existingCustomer?btn('Buka Customer 360',leadCall('go','Nasabah detail',l.profile)):'')+'</section>';
 if(recordTab==='Referral'||recordTab==='Identitas'){const kind=leadSourceKind(l.source),facts=[['Sumber',l.source]];if(recordTab==='Identitas')facts.push(['NIK',profile(l.profile)?.nik||'Belum diisi']);if(kind==='campaign')facts.push(['Campaign / referensi',l.campaignReference]);if(kind==='digital')facts.push(['Channel digital',l.digitalChannel],['Referensi digital',l.digitalReference]);if(kind==='referral')facts.push(['Jenis referral',l.referralType||'Belum ditetapkan'],['Pemberi referral',l.referral],['Cabang / organisasi asal',l.referralBranch],['Status penanganan referral',typeof referralHandling==='function'?referralHandling(l):l.referralStatus||'Belum diperbarui']);extra+=detailPanel(kind==='referral'?'Sumber & hubungan referral':'Sumber Lead',detailFacts(facts)+(!l.customerConverted?btn('Ubah sumber / referral',leadCall('leadEditSource',l.id)):'')+'<p class="hint">'+(kind==='referral'?'Riwayat Task, aktivitas dan konversi tetap terhubung melalui Lead ini.':'Lead ini tidak berasal dari referral.')+'</p>')}return extra+html};
function leadWorkflowConfig(){const r=leadPolicy();modal('Aturan Lead',field('SLA respons awal (hari kalender)','responseDays',r.responseDays,'number',true)+field('SLA kualifikasi (hari kalender)','qualificationDays',r.qualificationDays,'number',true)+area('Cabang yang tersedia (satu per baris)','branches',r.branches.join('\n'),true)+Object.entries(r.guidance).map(([k,v])=>area('Pedoman '+k,'grade_'+k,v,true)).join('')+'<p class="hint">SLA baru berlaku untuk Lead yang dibuat berikutnya. Lead lama tanpa snapshot memakai aturan saat ini. Pedoman membantu penilaian manual AO.</p>',f=>{const cfg=clone(db.config);cfg.leadWorkflow={responseDays:Number(f.responseDays),qualificationDays:Number(f.qualificationDays),branches:f.branches.split('\n').map(x=>x.trim()).filter(Boolean),guidance:Object.fromEntries(Object.keys(LEAD_GUIDANCE).map(k=>[k,f['grade_'+k]]))};saveMasters(cfg,'new')})}
const leadPreviousConfig=configScreenConnected;
configScreenConnected=function(){return leadPreviousConfig()+detailPanel('Lead: SLA, cabang & pedoman potensi',detailFacts([['Respons awal',leadPolicy().responseDays+' hari kalender'],['Kualifikasi',leadPolicy().qualificationDays+' hari kalender'],['Cabang',leadPolicy().branches.join(', ')]])+(authUser.role==='Superadmin'?btn('Atur workflow Lead','leadWorkflowConfig()',true):''))};
scaleNotifications=function(){const items=db.notifications||[];const rows=a=>a.map(n=>'<button class="notifrow" onclick="go(\''+({lead:'Lead detail',opportunity:'Opportunity detail',approval:'Persetujuan'}[n.kind]||'Aktivitas detail')+'\',\''+E(n.record)+'\')"><span><strong>'+E(n.title)+'</strong><small>'+E(n.note)+' · '+E(n.owner)+' · '+E(fmt(n.created))+'</small></span><b>↗</b></button>').join('')||empty('Tidak ada notifikasi.');return titleBlock('Notifikasi','Respons Lead, kualifikasi, Task dan eskalasi Opportunity. Owner tetap sampai ada Reassign.')+detailPanel('Perlu perhatian',rows(items.filter(n=>!n.resolved)))+detailPanel('Riwayat terselesaikan',rows(items.filter(n=>n.resolved)))};

const leadPreviousNewOpp=newOpp;
newOpp=function(pid='',lid=''){const l=db.leads.find(l=>l.id===lid);if(l?.status==='Closed')return toast('Aktifkan kembali Lead sebelum membuat Opportunity.');return leadPreviousNewOpp(pid,lid)};
leadIdentityEdit=function(id){let l;try{l=guardConvertedLead(id)}catch(e){return toast(e.message)}const p=profile(l.profile);if(p?.relation==='Customer')return toast('Identitas Customer tetap dikelola di Customer 360. Ubah kebutuhan Lead melalui Kualifikasi.');modal('Edit identitas Lead',field('Nama orang / perusahaan','name',p.name,'text',true)+field('Nama kontak','contact',p.contact||'')+field('Nomor telepon','phone',p.phone||'','tel',true)+field('NIK (opsional, 16 digit)','nik',p.nik||'')+field('Alamat','address',p.address||'')+field('Alamat usaha / tempat bekerja','businessAddress',p.businessAddress||'')+field('Pekerjaan / bidang usaha','occupation',p.occupation||'')+select('Minat produk','product',activeMaster('products').map(x=>x.name),l.product)+area('Kebutuhan awal','need',l.need||'',true),f=>{if(f.nik&&!/^\d{16}$/.test(f.nik))throw Error('NIK harus 16 digit.');Object.assign(p,{name:f.name,contact:f.contact,phone:f.phone,nik:f.nik,address:f.address,businessAddress:f.businessAddress,occupation:f.occupation});Object.assign(l,{need:f.need,product:f.product});record('Edit identitas Lead',l.id,p.name)})};
const leadPreviousExport=exportReport;
exportReport=function(kind){if(kind!=='Lead')return leadPreviousExport(kind);downloadCsv('leads',[['ID','Nama','Telepon','NIK','Sumber','Cabang','Tahap','Hasil kualifikasi','Potensi','Kebutuhan','Owner','Jenis referral','Pemberi referral','Status penanganan referral','Campaign','Channel digital','Referensi digital','Customer existing','Jumlah Opportunity','SLA respons (hari kalender)','SLA kualifikasi (hari kalender)','Status SLA'],...visible(db.leads).filter(l=>!month||l.created.startsWith(month)).map(l=>[l.id,pname(l.profile),profile(l.profile)?.phone,profile(l.profile)?.nik,l.source,l.branch||'Belum ditetapkan',leadLifecycle(l),l.qualification,l.grade,l.need,l.owner,l.referralType,l.referral,leadSourceKind(l.source)==='referral'?(typeof referralHandling==='function'?referralHandling(l):l.referralStatus||'Belum diperbarui'):'',l.campaignReference,l.digitalChannel,l.digitalReference,l.existingCustomer?'Ya':'Tidak',leadOpportunities(l).length,l.responseSlaDays??leadPolicy().responseDays,l.qualificationSlaDays??leadPolicy().qualificationDays,leadSla(l).label])])};
